function militaryInputs(){const monthlyBasic=Number($("monthlyBasicPay").value||0),housing=Number($("monthlyHousing").value||0),food=Number($("monthlyFood").value||0),special=Number($("monthlySpecialPay").value||0),bonus=Number($("militaryBonus").value||0),commitment=Number($("serviceCommitment").value||0),education=Number($("educationBenefit").value||0),realization=Number($("benefitRealization").value||0);const annualCash=(monthlyBasic+housing+food+special)*12,educationExpected=education*realization;return{grade:$("payGrade").value,monthlyBasic,housing,food,special,bonus,commitment,education,realization,educationExpected,annualCash}}
