renderMilitaryChoice=async job=>{selectedMilitary=job;$("militaryJobSearch").value=`${job.code} · ${job.title}`;const match=(job.occupations||[])[0];$("militaryJobSelected").innerHTML=`<strong>${escapeHtml(job.title)}</strong><small>CareerShield scores this specialty directly. Related civilian occupations are used only as background labor-market signals.</small>`;$("militaryJobSelected").hidden=false;selectedCareer=null;if(match){try{selectedCareer=await api(`/api/careers?code=${encodeURIComponent(match.code)}`)}catch{selectedCareer={code:match.code,name:job.title,description:job.title,relatedOccupations:job.occupations||[],industries:[],tasks:[],outlook:null,wage:null}}}else selectedCareer={code:job.code,name:job.title,description:job.title,relatedOccupations:[],industries:[],tasks:[],outlook:null,wage:null}};
militaryInputs=()=>{const monthlyBasic=Number($("monthlyBasicPay").value||0),housing=Number($("monthlyHousing").value||0),food=Number($("monthlyFood").value||0),special=Number($("monthlySpecialPay").value||0),bonus=Number($("militaryBonus").value||0),commitment=Number($("serviceCommitment").value||0),education=Number($("educationBenefit").value||0);return{grade:$("payGrade").value,dutyZip:$("dutyZip").value,dependentStatus:$("dependentStatus").value,monthlyBasic,housing,food,special,bonus,commitment,education,educationExpected:education,annualCash:(monthlyBasic+housing+food+special)*12}};

const calculateV411Base=calculate,setPathV411Base=setPath;
const selectedDegreePlan=()=>manualProgramMode?"":$("collegePlan").value.trim();
function validOfficialProgramUrl(){const value=$("manualProgramUrl").value.trim();if(!value)return"";try{const url=new URL(value);return /^https?:$/.test(url.protocol)?url.href:""}catch{return""}}
function selectedSchoolOfficialUrl(){const value=String(get(selectedSchool,"school.school_url")||"").trim();if(!value)return"";try{return new URL(/^https?:\/\//i.test(value)?value:`https://${value}`).href}catch{return""}}
function populateOfficialProgramUrl(){if(manualProgramMode)$("manualProgramUrl").value=selectedSchoolOfficialUrl()}
function setManualProgramMode(manual){manualProgramMode=manual;$("manualProgramFields").hidden=!manual;$("manualProgramToggle").hidden=manual;$("collegePlan").hidden=manual;$("collegePlanHint").hidden=manual;selectedProgram=null;selectedCareer=null;$("careerSelected").hidden=true;if(manual){populateOfficialProgramUrl();fillCareerDropdown([],"Enter a program name to load matching careers");$("targetCareerHint").textContent="Enter the program name above, then choose the closest matching O*NET career from this dropdown."}else{$("manualProgramName").value="";$("manualProgramUrl").value="";loadCollegeCareers()}}
$("manualProgramToggle").addEventListener("click",()=>setManualProgramMode(true));
$("useScorecardPrograms").addEventListener("click",()=>setManualProgramMode(false));
const loadManualProgramCareers=debounce(async()=>{if(!manualProgramMode)return;const name=$("manualProgramName").value.trim();selectedCareer=null;$("careerSelected").hidden=true;if(name.length<2)return fillCareerDropdown([],"Enter at least two letters to find matching careers");const select=$("targetCareerSelect");select.disabled=true;select.innerHTML='<option>Loading matching O*NET careers…</option>';try{const {results}=await api(`/api/careers?search=${encodeURIComponent(name)}`);fillCareerDropdown(results,"Choose the closest matching target career")}catch(error){fillCareerDropdown([],"Career options unavailable");$("targetCareerHint").textContent=error.message}},350);
$("manualProgramName").addEventListener("input",loadManualProgramCareers);
document.querySelectorAll(".path-choice").forEach(button=>button.addEventListener("click",()=>{$("collegePlanField").hidden=button.dataset.path!=="college"}));
calculate=()=>{const option=calculateV411Base();if(option.path==="college"){option.unitId=get(selectedSchool,"id");option.degreePlan=selectedDegreePlan();option.program=manualProgramMode?$("manualProgramName").value.trim():(selectedProgram?.title||$("collegePlan").options[$("collegePlan").selectedIndex]?.text||"Selected degree or program");option.degree=option.program;option.programSource=manualProgramMode?"user_entered":"college_scorecard";option.programVerificationLabel=manualProgramMode?"User-entered program, verify with school":"College Scorecard program suggestion";option.officialProgramUrl=manualProgramMode?validOfficialProgramUrl():null}if(option.path==="military"){option.branch=$("militaryBranch").value;option.career={...option.career,name:selectedMilitary?.title||option.career?.name};option.inputs={...option.inputs,gross:0,aid:0,debt:0,netCost:0,upfront:0,duration:0};option.metrics["Time to earnings"]=100;option.metrics["Debt & upfront cost"]=100;option.score=clamp(option.metrics["Financial outcome"]*.28+100*.17+100*.18+option.metrics["Employment demand"]*.15+option.metrics["AI resilience"]*.12+option.metrics["Career flexibility"]*.10)}return option};
setPath=(path,initial=false)=>{setPathV411Base(path,initial);const military=path==="military";$("providerField").hidden=true;$("careerField").hidden=military;if(military){$("costField").hidden=true;$("aidField").hidden=true;$("durationField").hidden=true;$("earnWhileField").hidden=true;$("startingPayField").hidden=true;$("cost").value="0";$("grants").value="0";$("debt").value="0";$("duration").value="0"}if(path==="college"){$("careerLabel").textContent="Degree plan";$("careerSearch").placeholder="Type a field such as nursing or accounting"}if(path==="trade"||path==="training"){$("careerLabel").textContent="Target career";$("careerSearch").placeholder="Type a career to choose"}};

