function showCombinedTraining(path){$("trainingModeField").hidden=!(path==="trade"||path==="training");document.querySelectorAll(".path-choice").forEach(button=>{const on=(button===combinedPathButton&&(path==="trade"||path==="training"))||button.dataset.path===path;button.classList.toggle("active",on);button.setAttribute("aria-checked",String(on))})}
combinedPathButton.addEventListener("click",()=>{const mode=$("trainingMode").value;setPath(mode);showCombinedTraining(mode)});
