const setPathV42Base=setPath;
setPath=(path,initial=false)=>{setPathV42Base(path,initial);showCombinedTraining(path);if(path==="college"){$("careerLabel").textContent="Target career";$("careerSearch").placeholder="Type the career this degree should lead to"}$("collegePlanField").hidden=path!=="college"};
$("schoolSearch").addEventListener("input",()=>{const select=$("collegePlan");select.disabled=true;select.innerHTML='<option value="">Select a school first</option>';$("collegePlanHint").textContent="Federal data can lag or group programs differently. Use these as suggestions, or add a program manually."});
$("addOption").addEventListener("click",event=>{if(activePath!=="college")return;if(manualProgramMode&&!$("manualProgramName").value.trim()){event.stopImmediatePropagation();$("formMessage").textContent="Enter the degree or program name before continuing.";return}if(manualProgramMode&&!validOfficialProgramUrl()){event.stopImmediatePropagation();$("formMessage").textContent="An official school or program webpage is required. Enter a complete http:// or https:// URL.";return}if(!manualProgramMode&&!selectedDegreePlan()){event.stopImmediatePropagation();$("formMessage").textContent="Choose a federal program suggestion or select ‘My program isn’t listed.’";return}if(!selectedCareer){event.stopImmediatePropagation();$("formMessage").textContent="Choose the closest matching target career from the O*NET dropdown."}},true);

const ASSISTANT_USAGE_KEY="careershield-v4-ai-usage",ASSISTANT_DAILY_LIMIT=10;
function assistantUsage(){const day=new Date().toISOString().slice(0,10);try{const saved=JSON.parse(localStorage.getItem(ASSISTANT_USAGE_KEY));return saved?.day===day?{day,count:Number(saved.count)||0}:{day,count:0}}catch{return{day,count:0}}}
function recordAssistantUse(){const usage=assistantUsage();usage.count+=1;localStorage.setItem(ASSISTANT_USAGE_KEY,JSON.stringify(usage));return usage}
function toggleAssistant(open){$("assistantPanel").hidden=!open;$("assistantToggle").setAttribute("aria-expanded",String(open));if(open)setTimeout(()=>$("assistantInput").focus(),50)}
function assistantBubble(text,type){const bubble=document.createElement("div");bubble.className=`assistant-bubble ${type}`;bubble.textContent=text;$("assistantMessages").appendChild(bubble);$("assistantMessages").scrollTop=$("assistantMessages").scrollHeight;return bubble}
async function askAssistant(question){const usage=assistantUsage();if(usage.count>=ASSISTANT_DAILY_LIMIT){assistantBubble("You’ve reached today’s 10-question AI Guide limit. Your questions reset tomorrow.","error");return}assistantBubble(question,"user");const waiting=assistantBubble("Thinking…","bot"),button=$("assistantSend");button.disabled=true;try{const ranked=[...comparisons].sort((a,b)=>b.score-a.score);const response=await fetch("/api/assistant",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({message:question,comparisons:ranked})});const data=await response.json().catch(()=>({}));if(response.status===429)throw new Error("You’re asking questions too quickly. Please wait about three minutes and try again.");if(!response.ok)throw new Error(data.error||"The AI guide could not answer right now.");recordAssistantUse();waiting.textContent=data.answer}catch(error){waiting.className="assistant-bubble error";waiting.textContent=error.message}finally{button.disabled=false;$("assistantMessages").scrollTop=$("assistantMessages").scrollHeight}}
$("assistantToggle").addEventListener("click",()=>toggleAssistant($("assistantPanel").hidden));$("assistantClose").addEventListener("click",()=>toggleAssistant(false));$("assistantForm").addEventListener("submit",event=>{event.preventDefault();const question=$("assistantInput").value.trim();if(!question)return;$("assistantInput").value="";askAssistant(question)});document.querySelectorAll(".assistant-prompts button").forEach(button=>button.addEventListener("click",()=>{toggleAssistant(true);askAssistant(button.textContent)}));

let targetCareerChoices=[],militarySpecialtyChoices=[];
function fillCareerDropdown(results,prompt){targetCareerChoices=results||[];const select=$("targetCareerSelect");select.innerHTML=`<option value="">${escapeHtml(prompt)}</option>`+targetCareerChoices.map((career,index)=>`<option value="${index}">${escapeHtml(career.name)} · ${escapeHtml(career.code)}</option>`).join("");select.disabled=!targetCareerChoices.length;$("targetCareerHint").textContent=targetCareerChoices.length?`${targetCareerChoices.length} related O*NET career${targetCareerChoices.length===1?"":"s"} available.`:"No related careers were returned. Try another choice."}
async function selectCareerFromDropdown(){if($("targetCareerSelect").value==="")return;const career=targetCareerChoices[Number($("targetCareerSelect").value)];if(!career)return;$("careerSearch").value=career.name;$("careerSelected").textContent="Loading career details…";$("careerSelected").hidden=false;selectedCareer=null;try{selectedCareer=await api(`/api/careers?code=${encodeURIComponent(career.code)}`);$("careerSelected").textContent=`Selected · ${selectedCareer.name} · ${selectedCareer.code}`;const median=Number(selectedCareer.wage?.annual_median||selectedCareer.wage?.annual_median_over||0);if(median&&!$("startingPay").value)$("startingPay").placeholder=`About ${money(median*.82)}`}catch(error){$("careerSelected").textContent=error.message}}
async function loadCollegeCareers(){if(manualProgramMode)return;const code=selectedDegreePlan();selectedCareer=null;$("careerSelected").hidden=true;if(!code)return fillCareerDropdown([],"Choose a degree or program first");const select=$("targetCareerSelect");select.disabled=true;select.innerHTML='<option>Loading careers related to this program…</option>';try{const {results}=await api(`/api/careers?education=${encodeURIComponent(code)}`);fillCareerDropdown(results,"Choose a career related to this program")}catch(error){fillCareerDropdown([],"Career options unavailable");$("targetCareerHint").textContent=error.message}}
async function loadTrainingCareers(){const select=$("targetCareerSelect");select.disabled=true;select.innerHTML='<option>Loading O*NET careers…</option>';try{const {results}=await api("/api/careers?catalog=occupations");fillCareerDropdown(results,"Choose a target career")}catch(error){fillCareerDropdown([],"Career options unavailable");$("targetCareerHint").textContent=error.message}}
async function loadMilitarySpecialties(){const category=$("militarySpecialtyCategory").value,select=$("militarySpecialtySelect");selectedMilitary=null;selectedCareer=null;$("militaryJobSelected").hidden=true;if(!category){select.disabled=true;select.innerHTML='<option value="">Choose a specialty category first</option>';return}select.disabled=true;select.innerHTML='<option>Loading official specialties…</option>';$("militarySpecialtyHint").textContent="Loading O*NET military crosswalk records.";try{const params=new URLSearchParams({military:category,branch:$("militaryBranch").value,track:$("militaryTrack").value}),data=await api(`/api/careers?${params}`);militarySpecialtyChoices=data.results||[];select.innerHTML='<option value="">Choose a military specialty</option>'+militarySpecialtyChoices.map((job,index)=>`<option value="${index}">${escapeHtml(job.code)} · ${escapeHtml(job.title.replace(/\s*\([^)]*\)\s*$/,""))}</option>`).join("");select.disabled=!militarySpecialtyChoices.length;$("militarySpecialtyHint").textContent=militarySpecialtyChoices.length?`${militarySpecialtyChoices.length} official ${category.toLowerCase()} specialt${militarySpecialtyChoices.length===1?"y":"ies"} for this branch and track.`:"No matching specialties were returned. Try another category."}catch(error){select.innerHTML='<option value="">Specialties unavailable</option>';$("militarySpecialtyHint").textContent=error.message}}
$("collegePlan").addEventListener("change",loadCollegeCareers);
$("targetCareerSelect").addEventListener("change",selectCareerFromDropdown);
$("militarySpecialtyCategory").addEventListener("change",loadMilitarySpecialties);
$("militarySpecialtySelect").addEventListener("change",()=>{if($("militarySpecialtySelect").value==="")return;const job=militarySpecialtyChoices[Number($("militarySpecialtySelect").value)];if(job)renderMilitaryChoice(job)});
[$("militaryBranch"),$("militaryTrack")].forEach(select=>select.addEventListener("change",loadMilitarySpecialties));
const setPathDropdownBase=setPath;
setPath=(path,initial=false)=>{setPathDropdownBase(path,initial);if(path==="trade"||path==="training")loadTrainingCareers();if(path==="college")loadCollegeCareers()};

let selectedBah=null;
const loadBah=debounce(async()=>{const zip=$("dutyZip").value.trim(),grade=$("payGrade").value,dependents=$("dependentStatus").value;selectedBah=null;if(zip.length!==5){$("monthlyHousing").value="0";$("bahStatus").textContent="Enter a five-digit duty ZIP to load the official 2026 DoD rate.";updateMilitarySummary();return}$("bahStatus").textContent="Loading the official 2026 DoD BAH rate…";try{selectedBah=await api(`/api/bah?zip=${encodeURIComponent(zip)}&grade=${encodeURIComponent(grade)}&dependents=${encodeURIComponent(dependents)}`);$("monthlyHousing").value=selectedBah.monthly;$("bahStatus").textContent=`Official 2026 rate for ${selectedBah.location} · ${grade} · ${dependents} dependents.`}catch(error){$("monthlyHousing").value="0";$("bahStatus").textContent=error.message}updateMilitarySummary()},250);
$("dutyZip").addEventListener("input",loadBah);
$("payGrade").addEventListener("change",loadBah);
$("dependentStatus").addEventListener("change",loadBah);

function applySelectedProgram(){const option=$("collegePlan").selectedOptions[0],index=Number(option?.dataset.programIndex);selectedProgram=option?.value!==""&&Number.isInteger(index)?schoolProgramChoices[index]:null;if(!selectedProgram)return;const credential=selectedProgram.credential.toLowerCase();const months=credential.includes("associate")?24:credential.includes("bachelor")?48:credential.includes("certificate")?12:credential.includes("master")||credential.includes("doctoral")||credential.includes("professional")?72:Number($("degree").value||48);const degreeOption=[...$("degree").options].find(item=>Number(item.value)===months);if(degreeOption)$("degree").value=degreeOption.value;schoolTuition();if(selectedProgram.debt)$("debt").value=Math.round(selectedProgram.debt);if(selectedProgram.earnings)$("startingPay").value=Math.round(selectedProgram.earnings);updateDebtGuidance();const facts=[selectedProgram.earnings?`reported earnings ${money(selectedProgram.earnings)}`:"earnings suppressed or unavailable",selectedProgram.debt?`reported median debt ${money(selectedProgram.debt)}`:"program debt suppressed or unavailable"];$("collegePlanHint").textContent=`College Scorecard: ${facts.join(" · ")}. Tuition is estimated from the school rate and credential length because federal data does not publish tuition by major.`}
$("collegePlan").addEventListener("change",applySelectedProgram);
$("schoolSearch").addEventListener("input",()=>{selectedProgram=null;schoolProgramChoices=[]});

const floatingInfoTooltip=document.createElement("div");
floatingInfoTooltip.className="floating-info-tooltip";
floatingInfoTooltip.setAttribute("role","tooltip");
floatingInfoTooltip.hidden=true;
document.body.appendChild(floatingInfoTooltip);
function showFloatingInfo(button){const text=button.dataset.tip;if(!text)return;floatingInfoTooltip.textContent=text;floatingInfoTooltip.hidden=false;const buttonRect=button.getBoundingClientRect(),tipRect=floatingInfoTooltip.getBoundingClientRect(),margin=8;let left=buttonRect.left+buttonRect.width/2-tipRect.width/2;left=Math.max(margin,Math.min(left,window.innerWidth-tipRect.width-margin));let top=buttonRect.top-tipRect.height-9;if(top<margin)top=Math.min(window.innerHeight-tipRect.height-margin,buttonRect.bottom+9);floatingInfoTooltip.style.left=`${Math.round(left)}px`;floatingInfoTooltip.style.top=`${Math.round(top)}px`}
function hideFloatingInfo(){floatingInfoTooltip.hidden=true}
document.addEventListener("pointerover",event=>{const button=event.target.closest?.(".info");if(button&&!button.contains(event.relatedTarget))showFloatingInfo(button)});
document.addEventListener("pointerout",event=>{const button=event.target.closest?.(".info");if(button&&!button.contains(event.relatedTarget))hideFloatingInfo()});
