// V4.3.4 career-investment timeline, data confidence, and social sharing.
function evidenceRegister(option){const accessed=option.dataRetrievedAt||new Date().toISOString(),rows=[],add=(field,source,status,confidence,note,url)=>rows.push({field,source,status,confidence,note,url,accessed});if(option.career?.code)add("Occupation identity and mapping","O*NET Web Services","official","High",`O*NET ${option.career.code}`,"https://www.onetcenter.org/web_services.html");else add("Occupation identity and mapping","CareerShield","missing","Limited","No O*NET code captured","");if(option.path==="college"){if(option.programSource==="college_scorecard")add("Institution and federal program suggestion","College Scorecard","official","High","Federal data may lag or group programs differently","https://collegescorecard.ed.gov/data/");else add("Degree or program name","Customer entry","user_entered","Limited","Confirm against the current official school catalog",option.programUrl||"");add("Current program existence","Official school catalog","needs_verification","Limited","A school webpage must be reviewed before a paid report may call the program current",option.programUrl||"");add("Institution cross-check","NCES/IPEDS","planned_source","Pending","Not yet connected to the live builder","https://nces.ed.gov/ipeds/Home/UseTheData")}if(option.path==="trade"){add("Apprenticeship sponsor and registration","Apprenticeship.gov / RAPIDS","needs_verification","Limited","Confirm the specific sponsor and current opportunity; no general live API is connected","https://www.apprenticeship.gov/")}if(option.path==="training"){add("Credential identity and issuer","Credential Engine Registry","planned_source","Pending","Search API integration is not yet connected","https://credentialengine.org/develop-solutions/")}if(option.path==="military"){add("Basic pay and allowances","DFAS / DoD","official","High","Official rate tables; eligibility and actual duty-location values still require confirmation","https://www.dfas.mil/militarymembers/payentitlements/Pay-Tables/");add("GI Bill school or employer approval","VA GI Bill Comparison Tool","needs_verification","Limited","Official public dataset integration is planned but not yet connected","https://www.va.gov/education/gi-bill-comparison-tool/schools-and-employers")}add("Wages, employment, and projections","U.S. Bureau of Labor Statistics","planned_source","Pending","BLS will become the labor-market economics authority after series mapping is implemented","https://www.bls.gov/developers/");add("Costs, debt, duration, and starting pay","Customer / CareerShield model","user_entered_or_estimated","Moderate","Review each material assumption and retain its original label","");return rows}
function dataConfidence(option){const official=[],entered=[],estimated=["10-year financial position","CareerShield factor scores"],verify=[];if(option.career?.code)official.push("O*NET occupation identity, tasks, and relationships");if(option.path==="college"&&option.programSource==="college_scorecard")official.push("College Scorecard school and federal program suggestion");if(option.path==="military")official.push("DFAS/DoD pay rates and O*NET military crosswalk");if(option.programSource==="user_entered")entered.push("Degree or program name");entered.push("Costs, aid, debt, timeline, and pay assumptions");if(option.path==="trade")entered.push("Apprenticeship wage progression and fees");if(option.path==="training")entered.push("Completion and placement assumptions");if(option.path==="military")entered.push("Duty location, grade, bonus, and service assumptions");if(option.metrics?.["AI resilience"]!=null)estimated.push("AI resilience heuristic");if(option.inputs?.starting)estimated.push("Starting earnings projection");if(option.programSource==="user_entered")verify.push("Confirm the program in the current official school catalog");if(option.path==="college")verify.push("Cross-check IPEDS and confirm final aid, attendance cost, and borrowing");if(option.path==="trade")verify.push("Confirm sponsor registration, wage schedule, hours, and completion rules");if(option.path==="training")verify.push("Confirm the credential, issuer, completion, and placement claims");if(option.path==="military")verify.push("Confirm specialty availability, eligibility, benefits, and commitment");verify.push("BLS wage and projection cross-check is pending live integration");const evidence=evidenceRegister(option),score=clamp(82-(entered.length*4)-(verify.length*5)+(official.length*6)),label=score>=78?"High":score>=62?"Moderate":"Limited";return{score,label,official,entered,estimated,verify,evidence,evidenceVersion:1}}
function buildInvestmentTimeline(option,startAge){const years=[],durationYears=Math.max(0,Number(option.inputs?.duration||0)/12),netCost=Number(option.inputs?.netCost||0),debtDrag=Number(option.inputs?.debt||0)*.15,earnWhile=Number(option.inputs?.earnWhile||0),starting=Number(option.inputs?.starting||option.annualMedian||0),m=option.militaryComp,t=option.tradeComp,c=option.trainingComp;let position=-(netCost+debtDrag);for(let year=0;year<=10;year++){if(year>0){let annual=starting;if(m){const serviceYears=Number(m.commitment||0)/12;annual=year<=serviceYears?Number(m.annualCash||0):Number(option.inputs?.civilianStarting||starting);if(year===1)annual+=Number(m.bonus||0);if(year===Math.max(1,Math.ceil(serviceYears)))annual+=Number(m.educationExpected||m.education||0)}else if(t){const programYears=Math.max(1,Number(t.months||0)/12),progress=Math.min(1,year/programYears),wage=Number(t.start||0)+(Number(t.journey||0)-Number(t.start||0))*progress;annual=wage*Number(t.hoursWeek||40)*Number(t.weeksYear||50)}else if(c){annual=year<=Number(c.trainingYears||0)?Number(c.earnWhile||0):Number(c.success||0)*Number(c.salary||0)+(1-Number(c.success||0))*Number(c.fallback||0)}else if(year<=durationYears)annual=earnWhile;else annual=starting*Math.pow(1.03,Math.max(0,year-Math.ceil(durationYears)-1));position+=annual}years.push({age:startAge+year,year,position:Math.round(position)})}return years}
const calculateBeforeInvestmentAnalysis=calculate;
calculate=()=>{const option=calculateBeforeInvestmentAnalysis(),startAge=Math.max(14,Math.min(70,Number($("currentAge").value||18)));option.startAge=startAge;option.endAge=startAge+10;option.timeline=buildInvestmentTimeline(option,startAge);option.tenYearNet=option.timeline.at(-1).position;option.dataConfidence=dataConfidence(option);return option};
function timelineFor(option){const age=Number(option.startAge||18);return Array.isArray(option.timeline)&&option.timeline.length===11?option.timeline:buildInvestmentTimeline(option,age)}
function renderFinancialTimeline(){const target=$("financialTimeline"),ranked=[...comparisons].sort((a,b)=>tenYearValue(b)-tenYearValue(a));target.hidden=!ranked.length;if(!ranked.length)return;const start=Math.min(...ranked.map(o=>Number(o.startAge||18))),end=start+10,largest=Math.max(1,...ranked.flatMap(o=>timelineFor(o).map(point=>Math.abs(point.position))));target.innerHTML=`<div class="timeline-head"><div><span>10-YEAR CAREER INVESTMENT TIMELINE</span><h3>Where could each path leave you financially?</h3><p>Age ${start} through ${end}. Cumulative position combines earnings, training income, costs, debt financing drag, and applicable military compensation or benefits.</p></div><strong>Age ${end}</strong></div><div class="timeline-scroll"><div class="timeline-grid">${ranked.map((option,index)=>`<div class="timeline-row"><div class="timeline-label"><i style="--path-color:${["#155eef","#0a8f68","#a65a09","#7046b5"][index]}"></i><strong>${escapeHtml(option.savedLabel||option.name)}</strong><small>${money(timelineFor(option).at(-1).position)} at age ${option.endAge||Number(option.startAge||18)+10}</small></div><div class="timeline-points">${timelineFor(option).map(point=>`<div class="timeline-point"><span style="height:${Math.max(5,Math.round(Math.abs(point.position)/largest*100))}%" class="${point.position<0?"negative":"positive"}"></span><b>${point.age}</b><small>${money(point.position)}</small></div>`).join("")}</div></div>`).join("")}</div></div><p class="timeline-disclaimer">Directional estimate, not a guarantee. Open Data Confidence on each path to see what is official, entered, estimated, or still needs verification.</p>`}
function shareText(ranked){const start=Number(ranked[0]?.startAge||18),end=start+10,lines=ranked.map((o,i)=>`${i+1}. ${o.program||o.savedLabel||o.name} → ${o.career?.name||o.pathLabel}: ${money(tenYearValue(o))}`);return`CareerShield: who is financially ahead from age ${start} to ${end}?\n\n${lines.join("\n")}\n\nDirectional estimates—verify assumptions before deciding.`}
function downloadShareCard(ranked){const canvas=document.createElement("canvas");canvas.width=1080;canvas.height=1080;const ctx=canvas.getContext("2d"),start=Number(ranked[0]?.startAge||18),end=start+10;ctx.fillStyle="#071b30";ctx.fillRect(0,0,1080,1080);ctx.fillStyle="#5ea2ff";ctx.font="700 28px Arial";ctx.fillText("CAREERSHIELD · 10-YEAR COMPARISON",70,90);ctx.fillStyle="#fff";ctx.font="800 58px Arial";ctx.fillText(`Who is ahead at age ${end}?`,70,170);ctx.font="400 25px Arial";ctx.fillStyle="#bed0e0";ctx.fillText(`Career investment position from age ${start} to ${end}`,70,215);ranked.slice(0,4).forEach((o,i)=>{const y=310+i*155;ctx.fillStyle=["#155eef","#0a8f68","#d47a18","#8b5bd1"][i];ctx.fillRect(70,y-35,12,100);ctx.fillStyle="#fff";ctx.font="700 30px Arial";ctx.fillText(String(o.program||o.savedLabel||o.name).slice(0,43),105,y);ctx.fillStyle="#bed0e0";ctx.font="400 23px Arial";ctx.fillText(String(o.career?.name||o.pathLabel).slice(0,55),105,y+38);ctx.fillStyle="#fff";ctx.font="800 35px Arial";ctx.textAlign="right";ctx.fillText(money(tenYearValue(o)),1010,y+15);ctx.textAlign="left"});ctx.fillStyle="#bed0e0";ctx.font="400 20px Arial";ctx.fillText("Directional estimates. Verify costs, pay, benefits, and eligibility.",70,1010);canvas.toBlob(blob=>{const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`careershield-age-${start}-to-${end}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)},"image/png")}
