// Retrieve official evidence automatically after a path is added. User inputs remain
// unchanged; official values are stored as traceable benchmarks for review and reports.
function mergeAutomaticEvidence(option,result){option.liveEvidence=result;option.dataRetrievedAt=result.retrievedAt||new Date().toISOString();const confidence=dataConfidence(option),rows=confidence.evidence.filter(row=>!["U.S. Bureau of Labor Statistics","NCES/IPEDS","Credential Engine Registry","VA GI Bill Comparison Tool"].includes(row.source));const add=(field,source,status,level,note,url)=>rows.push({field,source,status,confidence:level,note,url,accessed:option.dataRetrievedAt});if(result.bls?.status==="official"){option.blsBenchmark=result.bls;confidence.official.push(`BLS OEWS ${result.bls.release} wage benchmark`);confidence.verify=confidence.verify.filter(item=>!item.startsWith("BLS wage"));add("National occupation wage benchmark","U.S. Bureau of Labor Statistics","official","High",`${result.bls.soc}${result.bls.annualMedian?` · annual median ${money(result.bls.annualMedian)}`:" · profile retrieved"}`,result.bls.url)}else add("Wages and employment","U.S. Bureau of Labor Statistics",result.bls?.status||"unavailable","Pending",result.bls?.note||"No matching detailed OEWS profile was returned.",result.bls?.url||"https://www.bls.gov/oes/tables.htm");if(option.path==="college"){if(result.ipeds?.status==="official"){option.ipedsCrossCheck=result.ipeds;confidence.official.push(`NCES/IPEDS institution record (UNITID ${result.ipeds.unitId})`);confidence.verify=confidence.verify.filter(item=>!item.startsWith("Cross-check IPEDS"));add("Institution identity","NCES/IPEDS","official","High",result.ipeds.institutionNameMatched===false?"UNITID retrieved; school-name text did not match exactly and needs review.":"College Navigator institution record retrieved by UNITID.",result.ipeds.url)}else add("Institution identity","NCES/IPEDS",result.ipeds?.status||"unavailable","Pending",result.ipeds?.note||"IPEDS record was not retrieved.",result.ipeds?.url||"https://nces.ed.gov/ipeds/Home/UseTheData");if(result.va?.status==="official"){option.vaGiBillMatches=result.va.matches||[];confidence.official.push("VA GI Bill Comparison Tool search results");add("GI Bill approved-school search","VA GI Bill Comparison Tool","official_source_match",result.va.matches?.length?"Moderate":"Limited",result.va.matches?.length?`${result.va.matches.length} possible match${result.va.matches.length===1?"":"es"} retrieved; confirm the exact facility before relying on benefits.`:"No matching approved facility was returned; this is not proof of ineligibility.",result.va.url)}else add("GI Bill approved-school search","VA GI Bill Comparison Tool",result.va?.status||"unavailable","Pending",result.va?.note||"VA search was not available.",result.va?.url||"https://www.va.gov/education/gi-bill-comparison-tool/schools-and-employers")}if(option.path==="training"){if(result.credential?.status==="official"){option.credentialRegistryMatches=result.credential.matches||[];confidence.official.push("Credential Engine Registry search results");add("Credential identity and issuer","Credential Engine Registry","official_source_match",result.credential.matches?.length?"Moderate":"Limited",result.credential.matches?.length?`${result.credential.matches.length} possible Registry match${result.credential.matches.length===1?"":"es"} retrieved; confirm the exact credential and issuer.`:"No Registry match was returned; this is not proof the credential is invalid.",result.credential.url)}else add("Credential identity and issuer","Credential Engine Registry",result.credential?.status||"unavailable","Pending",result.credential?.note||"Registry search was not available.",result.credential?.url||"https://credreg.net/registry/searchapi")}confidence.official=[...new Set(confidence.official)];confidence.evidence=rows;confidence.evidenceVersion=2;confidence.score=clamp(confidence.score+[result.bls?.status==="official",result.ipeds?.status==="official",result.credential?.status==="official",result.va?.status==="official"].filter(Boolean).length*5);confidence.label=confidence.score>=78?"High":confidence.score>=62?"Moderate":"Limited";option.dataConfidence=confidence;return option}
async function retrieveAutomaticEvidence(option){try{const response=await fetch("/api/evidence",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path:option.path,soc:option.career?.code,unitId:option.unitId,schoolName:option.path==="college"?option.name:"",program:option.program||option.trainingComp?.type,provider:option.name})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Evidence retrieval failed");mergeAutomaticEvidence(option,result);save();render()}catch(error){option.evidenceRetrievalError=error.message;save();render()}}
