async function downloadFreeComparisonSummary(ranked){const canvas=document.createElement("canvas");canvas.width=1275;canvas.height=1650;const ctx=canvas.getContext("2d"),start=Number(ranked[0]?.startAge||18),end=start+10;ctx.fillStyle="#f3f7fc";ctx.fillRect(0,0,1275,1650);ctx.fillStyle="#071b30";ctx.fillRect(0,0,1275,310);const logo=await loadCanvasLogo();if(logo)ctx.drawImage(logo,70,50,350,140);else{ctx.fillStyle="#fff";ctx.font="800 42px Arial";ctx.fillText("CareerShield",70,105)}ctx.fillStyle="#83b5ff";ctx.font="800 23px Arial";ctx.fillText("FREE CAREER INVESTMENT COMPARISON",70,210);ctx.fillStyle="#fff";ctx.font="800 48px Arial";ctx.fillText(`Where could each path leave you by age ${end}?`,70,270);ctx.fillStyle="#27445f";ctx.font="400 22px Arial";ctx.fillText(`Directional outlook from age ${start} to ${end} · Generated ${new Date().toLocaleDateString()}`,70,350);const colors=["#155eef","#0a8f68","#d47a18","#7046b5"];ranked.slice(0,4).forEach((option,index)=>{const y=395+index*250,confidence=option.dataConfidence||dataConfidence(option),factors=Object.entries(option.metrics||{}).sort((a,b)=>b[1]-a[1]),strongest=factors[0]?.[0]||"Not available",risk=factors.at(-1)?.[0]||"Not available";ctx.fillStyle="#fff";ctx.beginPath();ctx.roundRect(55,y,1165,220,20);ctx.fill();ctx.fillStyle=colors[index];ctx.fillRect(55,y,13,220);ctx.fillStyle="#071b30";ctx.font="800 30px Arial";canvasText(ctx,option.program||option.savedLabel||option.name,95,y+48,690);ctx.fillStyle="#536a80";ctx.font="400 21px Arial";canvasText(ctx,`${option.career?.name||option.pathLabel} · ${option.pathLabel}`,95,y+84,690);if(index===0){ctx.fillStyle="#e8f8f1";ctx.beginPath();ctx.roundRect(95,y+105,175,35,18);ctx.fill();ctx.fillStyle="#087a55";ctx.font="800 16px Arial";ctx.fillText("LEADING PATH",116,y+129)}ctx.fillStyle="#071b30";ctx.font="800 48px Arial";ctx.textAlign="right";ctx.fillText(`${option.score}/100`,1170,y+55);ctx.fillStyle="#536a80";ctx.font="700 17px Arial";ctx.fillText("CAREERSHIELD SCORE",1170,y+82);ctx.textAlign="left";const facts=[["10-YEAR POSITION",money(tenYearValue(option))],["EXPECTED DEBT",money(option.inputs?.debt||0)],["DATA CONFIDENCE",`${confidence.label} · ${confidence.score}/100`]];facts.forEach((fact,i)=>{const x=330+i*275;ctx.fillStyle="#7a8a9b";ctx.font="800 14px Arial";ctx.fillText(fact[0],x,y+125);ctx.fillStyle="#102f4b";ctx.font="800 23px Arial";canvasText(ctx,fact[1],x,y+155,245)});ctx.fillStyle="#315b8d";ctx.font="700 17px Arial";canvasText(ctx,`Strongest factor: ${strongest}`,95,y+190,500);ctx.fillStyle="#9a5b12";canvasText(ctx,`Biggest tradeoff: ${risk}`,620,y+190,500)});const footerY=1425;ctx.fillStyle="#071b30";ctx.fillRect(0,footerY,1275,225);ctx.fillStyle="#fff";ctx.font="800 25px Arial";ctx.fillText("Before you commit",70,1480);ctx.fillStyle="#c5d8e8";ctx.font="400 20px Arial";ctx.fillText("Verify costs, aid, borrowing, pay, eligibility, program status, and deadlines with official sources.",70,1520);ctx.fillText("CareerShield estimates are decision support—not a guarantee or financial, admissions, recruiting, or career advice.",70,1555);ctx.fillStyle="#83b5ff";ctx.font="800 19px Arial";ctx.fillText(location.hostname||"CareerShield",70,1605);ctx.textAlign="right";ctx.fillText("CAREERSHIELD · RUN THE NUMBERS",1205,1605);ctx.textAlign="left";canvas.toBlob(blob=>{const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`careershield-free-comparison-age-${start}-to-${end}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)},"image/png")}
