// Treat military education benefits as education support used over time, not
// as a lump-sum cash payment in the service-transition year.
buildInvestmentTimeline=(option,startAge)=>{const years=[],durationYears=Math.max(0,Number(option.inputs?.duration||0)/12),netCost=Number(option.inputs?.netCost||0),debtDrag=Number(option.inputs?.debt||0)*.15,earnWhile=Number(option.inputs?.earnWhile||0),starting=Number(option.inputs?.starting||option.annualMedian||0),m=option.militaryComp,t=option.tradeComp,c=option.trainingComp;let position=-(netCost+debtDrag);for(let year=0;year<=10;year++){if(year>0){let annual=starting;if(m){const serviceYears=Number(m.commitment||0)/12,educationYears=4,educationAnnual=Number(m.educationExpected||0)/educationYears;annual=year<=serviceYears?Number(m.annualCash||0):Number(option.inputs?.civilianStarting||starting);if(year===1)annual+=Number(m.bonus||0);if(year>serviceYears&&year<=serviceYears+educationYears)annual+=educationAnnual}else if(t){const programYears=Math.max(1,Number(t.months||0)/12),progress=Math.min(1,year/programYears),wage=Number(t.start||0)+(Number(t.journey||0)-Number(t.start||0))*progress;annual=wage*Number(t.hoursWeek||40)*Number(t.weeksYear||50)}else if(c){annual=year<=Number(c.trainingYears||0)?Number(c.earnWhile||0):Number(c.success||0)*Number(c.salary||0)+(1-Number(c.success||0))*Number(c.fallback||0)}else if(year<=durationYears)annual=earnWhile;else annual=starting*Math.pow(1.03,Math.max(0,year-Math.ceil(durationYears)-1));position+=annual}years.push({age:startAge+year,year,position:Math.round(position)})}return years};
function applyMilitaryBenefitTiming(option){if(option.path!=="military"||option.benefitTimingVersion===1)return option;const expected=Number(option.militaryComp?.educationExpected||0),serviceYears=Number(option.militaryComp?.commitment||0)/12,recognizedYears=Math.max(0,Math.min(4,5-serviceYears)),recognizedFiveYear=expected*(recognizedYears/4);option.fiveYearNet=Number(option.fiveYearNet||0)-expected+recognizedFiveYear;option.metrics["Financial outcome"]=clamp(42+(option.fiveYearNet-140000)/7000);option.score=clamp(option.metrics["Financial outcome"]*.28+option.metrics["Time to earnings"]*.17+option.metrics["Debt & upfront cost"]*.18+option.metrics["Employment demand"]*.15+option.metrics["AI resilience"]*.12+option.metrics["Career flexibility"]*.10);option.timeline=buildInvestmentTimeline(option,Number(option.startAge||18));option.tenYearNet=option.timeline.at(-1).position;option.benefitTimingVersion=1;option.militaryComp.educationRecognition={method:"Spread across four post-service years when presumed used",annualAmount:expected/4,firstUseYear:Math.floor(serviceYears)+1};if(option.liveEvidence)mergeAutomaticEvidence(option,option.liveEvidence);else option.dataConfidence=dataConfidence(option);return option}
const calculateBeforeMilitaryBenefitTiming=calculate;
calculate=()=>applyMilitaryBenefitTiming(calculateBeforeMilitaryBenefitTiming());
let militaryBenefitTimingMigrated=false;comparisons.forEach(option=>{if(option.path==="military"&&option.benefitTimingVersion!==1){applyMilitaryBenefitTiming(option);militaryBenefitTimingMigrated=true}});if(militaryBenefitTimingMigrated)save(false);render();

