let takeHomeShare=null;
function comparisonFingerprint(){return JSON.stringify(comparisons.map(option=>({id:option.id,score:option.score,tenYearNet:tenYearValue(option),updated:option.dataRetrievedAt||""})))}
async function ensureTakeHomeShare(){const fingerprint=comparisonFingerprint();if(takeHomeShare?.fingerprint===fingerprint)return takeHomeShare;const response=await fetch("/api/plans?share=create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({plans:comparisons})}),contentType=response.headers.get("content-type")||"",data=contentType.includes("application/json")?await response.json().catch(()=>({})):{};if(!response.ok){if(response.status===404)throw new Error("The updated plans function is not deployed yet. Upload netlify/functions/plans.js and redeploy.");throw new Error(data.error||`The take-home service returned error ${response.status}.`)}const url=new URL(location.pathname,location.origin);url.searchParams.set("family",data.token);takeHomeShare={fingerprint,url:url.toString(),expiresAt:data.expiresAt};return takeHomeShare}
function takeHomeMarkup(share=null){return `<section class="take-home-handoff"><div class="take-home-copy"><span>CONTINUE THIS DECISION AT HOME</span><h3>Your counselor helped you compare ${comparisons.length} path${comparisons.length===1?"":"s"}.</h3><p>Scan the QR code or use the private recovery link to reopen this exact CareerShield comparison with a parent or guardian.</p><div class="take-home-known"><strong>What you know now</strong><span>CareerShield scores</span><span>10-year outlook</span><span>Cost and debt</span><span>Time to earnings</span><span>Employment demand</span></div><div class="take-home-missing"><strong>What you have not checked yet</strong><span>How lower starting pay changes the result</span><span>What happens if costs are higher</span><span>When one path overtakes another</span><span>Which assumptions still need verification</span></div></div><div class="take-home-access">${share?`<img src="/api/plans?share=qr&url=${encodeURIComponent(share.url)}" alt="QR code to reopen this comparison"><b>${escapeHtml(share.url)}</b><small>Read-only link · expires ${escapeHtml(new Date(share.expiresAt).toLocaleDateString())}</small>`:'<div class="qr-placeholder">QR</div><b>Create the link before printing</b><small>No student name is embedded in the QR code.</small>'}<button id="createTakeHomeLink" class="primary" type="button">${share?"Print take-home plan":"Create QR & print plan"}</button><p id="takeHomeStatus" role="status"></p></div></section>`}
const renderPlanBeforeTakeHome=renderPlan;
renderPlan=ranked=>{renderPlanBeforeTakeHome(ranked);const section=$("planSection");if(!ranked.length||!section)return;const notes=section.querySelector(".print-plan-notes"),handoff=document.createElement("div");handoff.innerHTML=takeHomeMarkup(takeHomeShare?.fingerprint===comparisonFingerprint()?takeHomeShare:null);notes?.before(handoff.firstElementChild);const oldPrint=section.querySelector(":scope > #printPlan");if(oldPrint)oldPrint.hidden=true;section.querySelector("#createTakeHomeLink")?.addEventListener("click",async event=>{const button=event.currentTarget,status=section.querySelector("#takeHomeStatus");button.disabled=true;button.textContent="Creating secure link…";try{const share=await ensureTakeHomeShare();renderPlan([...comparisons].sort((a,b)=>b.score-a.score));const image=section.querySelector(".take-home-access img");if(image)await image.decode().catch(()=>{});window.print()}catch(error){button.disabled=false;button.textContent="Try again";status.textContent=error.message}})};
render();

window.CareerShieldFamilyReview=new URLSearchParams(location.search).has("family");
function weakestFactor(option){return Object.entries(option.metrics||{}).sort((a,b)=>a[1]-b[1])[0]?.[0]||"Missing assumptions"}
function renderFamilyReview(createdAt,expiresAt){document.body.classList.add("family-review-mode");const ranked=[...comparisons].sort((a,b)=>tenYearValue(b)-tenYearValue(a)),host=document.createElement("section"),start=Number(ranked[0]?.startAge||18),end=start+10;host.id="familyReview";host.className="family-review";host.innerHTML=`<div class="family-review-head"><span>FAMILY REVIEW</span><h1>You’ve already compared your options.<br>Now see what could change the decision.</h1><p>This read-only comparison was prepared during a CareerShield session. Review the biggest financial differences together before anyone commits, borrows, enrolls, or signs.</p><small>Shared ${escapeHtml(new Date(createdAt).toLocaleDateString())} · Available through ${escapeHtml(new Date(expiresAt).toLocaleDateString())}</small></div><div class="family-review-grid">${ranked.map((option,index)=>{const confidence=option.dataConfidence||dataConfidence(option);return `<article class="${index===0?"family-leading":""}"><span>${index===0?"LEADING 10-YEAR POSITION":`PATH ${index+1}`}</span><h2>${escapeHtml(option.program||option.savedLabel||option.name)}</h2><p>${escapeHtml(option.career?.name||option.pathLabel)}</p><dl><div><dt>Position at age ${end}</dt><dd>${money(tenYearValue(option))}</dd></div><div><dt>Expected debt</dt><dd>${money(option.inputs?.debt||0)}</dd></div><div><dt>Time before full earnings</dt><dd>${Math.round(Number(option.inputs?.duration||0))} months</dd></div><div><dt>Data confidence</dt><dd>${escapeHtml(confidence.label)} · ${confidence.score}/100</dd></div></dl><b>Watch closely: ${escapeHtml(weakestFactor(option))}</b></article>`}).join("")}</div><div class="family-next"><div><span>THE NEXT QUESTION</span><h2>What could reverse this ranking?</h2><p>Deep Analysis stress-tests lower pay, higher costs, delayed completion, break-even timing, and unresolved assumptions. It checks available sources and flags anything the family still needs to verify.</p></div><button id="familyDeepAnalysis" class="primary" type="button">Unlock Deep Analysis · $9.99</button><small>Login and a synchronized comparison are required before checkout.</small></div>`;document.querySelector("main")?.prepend(host);$("familyDeepAnalysis")?.addEventListener("click",()=>$("buyDeepAnalysis")?.click());host.scrollIntoView({block:"start"})}
async function loadFamilyReview(){const token=new URLSearchParams(location.search).get("family");if(!token)return;document.body.classList.add("family-review-loading");try{const response=await fetch(`/api/plans?share=open&token=${encodeURIComponent(token)}`),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"This comparison could not be reopened.");comparisons=Array.isArray(data.plans)?data.plans.slice(0,4):[];comparisons.forEach(option=>applyMilitaryBenefitTiming(option));render();updateSavedProgress();renderFamilyReview(data.createdAt,data.expiresAt)}catch(error){const notice=document.createElement("section");notice.className="family-review family-review-error";notice.innerHTML=`<h1>We couldn’t reopen this comparison.</h1><p>${escapeHtml(error.message)}</p><a class="primary" href="/">Start a new free comparison</a>`;document.querySelector("main")?.prepend(notice)}finally{document.body.classList.remove("family-review-loading")}}
loadFamilyReview();

async function loadQrForCanvas(url){const response=await fetch(`/api/plans?share=qr&url=${encodeURIComponent(url)}`);if(!response.ok)throw new Error("The QR code could not be generated.");const blob=await response.blob(),objectUrl=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve({image,objectUrl});image.onerror=()=>reject(new Error("The QR code image could not be loaded."));image.src=objectUrl})}catch(error){URL.revokeObjectURL(objectUrl);throw error}}
async function downloadTakeHomeComparison(ranked){const button=freeComparisonButton,original=button?.textContent;try{if(button){button.textContent="Creating private QR…";button.setAttribute("aria-busy","true")}const share=await ensureTakeHomeShare(),qr=await loadQrForCanvas(share.url),canvas=document.createElement("canvas");canvas.width=1275;canvas.height=1800;const ctx=canvas.getContext("2d"),start=Number(ranked[0]?.startAge||18),end=start+10,colors=["#155eef","#0a8f68","#d47a18","#7046b5"];ctx.fillStyle="#f3f7fc";ctx.fillRect(0,0,1275,1800);ctx.fillStyle="#071b30";ctx.fillRect(0,0,1275,255);const logo=await loadCanvasLogo();if(logo)ctx.drawImage(logo,65,35,320,128);else{ctx.fillStyle="#fff";ctx.font="800 42px Arial";ctx.fillText("CareerShield",65,95)}ctx.fillStyle="#83b5ff";ctx.font="800 21px Arial";ctx.fillText("FREE TAKE-HOME CAREER COMPARISON",65,185);ctx.fillStyle="#fff";ctx.font="800 43px Arial";ctx.fillText(`Where could each path leave you by age ${end}?`,65,230);ranked.slice(0,4).forEach((option,index)=>{const y=300+index*220,confidence=option.dataConfidence||dataConfidence(option),factors=Object.entries(option.metrics||{}).sort((a,b)=>a[1]-b[1]),risk=factors[0]?.[0]||"Assumptions need review";ctx.fillStyle="#fff";ctx.beginPath();ctx.roundRect(55,y,1165,190,18);ctx.fill();ctx.fillStyle=colors[index];ctx.fillRect(55,y,12,190);ctx.fillStyle="#071b30";ctx.font="800 27px Arial";canvasText(ctx,option.program||option.savedLabel||option.name,92,y+43,680);ctx.fillStyle="#536a80";ctx.font="400 18px Arial";canvasText(ctx,option.career?.name||option.pathLabel,92,y+75,680);ctx.fillStyle="#071b30";ctx.font="800 40px Arial";ctx.textAlign="right";ctx.fillText(`${option.score}/100`,1170,y+48);ctx.font="800 25px Arial";ctx.fillText(money(tenYearValue(option)),1170,y+84);ctx.textAlign="left";const facts=[`Debt: ${money(option.inputs?.debt||0)}`,`Time to earnings: ${Math.round(Number(option.inputs?.duration||0))} months`,`Confidence: ${confidence.label} ${confidence.score}/100`];ctx.fillStyle="#315b8d";ctx.font="700 16px Arial";facts.forEach((fact,i)=>ctx.fillText(fact,92+i*330,y+125));ctx.fillStyle="#9a5b12";ctx.font="700 16px Arial";canvasText(ctx,`Watch closely: ${risk}`,92,y+163,800)});const handoffY=1210;ctx.fillStyle="#e8f2ff";ctx.beginPath();ctx.roundRect(55,handoffY,1165,470,22);ctx.fill();ctx.fillStyle="#155eef";ctx.font="800 18px Arial";ctx.fillText("CONTINUE THIS DECISION AT HOME",90,handoffY+48);ctx.fillStyle="#071b30";ctx.font="800 32px Arial";ctx.fillText("Scan to reopen this exact comparison.",90,handoffY+92);ctx.fillStyle="#536a80";ctx.font="400 18px Arial";ctx.fillText("Review it with a parent or guardian, then see what could change the decision.",90,handoffY+126);ctx.fillStyle="#071b30";ctx.font="800 20px Arial";ctx.fillText("What you have not checked yet",90,handoffY+183);ctx.fillStyle="#536a80";ctx.font="400 17px Arial";["• What if starting pay is lower?","• What if costs or completion time are higher?","• When does one path overtake another?","• Which assumptions still need verification?"].forEach((line,i)=>ctx.fillText(line,90,handoffY+220+i*34));ctx.drawImage(qr.image,855,handoffY+48,275,275);URL.revokeObjectURL(qr.objectUrl);ctx.fillStyle="#071b30";ctx.font="700 14px Arial";ctx.textAlign="center";canvasText(ctx,share.url,992,handoffY+350,360);ctx.fillStyle="#536a80";ctx.font="400 13px Arial";ctx.fillText(`Private read-only link · expires ${new Date(share.expiresAt).toLocaleDateString()}`,992,handoffY+380);ctx.fillStyle="#155eef";ctx.font="800 17px Arial";ctx.fillText("Deep Analysis available for $9.99",992,handoffY+420);ctx.textAlign="left";ctx.fillStyle="#536a80";ctx.font="400 15px Arial";ctx.fillText("Directional decision support—not a guarantee. Verify costs, pay, eligibility, benefits, and program status.",65,1745);await new Promise((resolve,reject)=>canvas.toBlob(blob=>{if(!blob)return reject(new Error("The comparison image could not be created."));const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`careershield-take-home-comparison-age-${start}-to-${end}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);resolve()},"image/png"))}catch(error){window.alert(error.message)}finally{if(button){button.textContent=original;button.removeAttribute("aria-busy")}}}
downloadFreeComparisonSummary=downloadTakeHomeComparison;

// V4.4.7 uses a self-contained family worksheet instead of QR codes or
// anonymous shared links. Families continue on the student's device/account.
function familyWorksheetMarkup(ranked){const leader=ranked[0];return `<section class="family-worksheet"><span>CONTINUE THIS DECISION AT HOME</span><h3>Use this page for a 15-minute family review.</h3><p>The comparison is a starting point—not the final decision. Review the leading path, challenge the assumptions, and agree on what must be verified before committing.</p><div class="family-worksheet-grid"><div><strong>What the comparison shows</strong><ul><li>Current leader: ${escapeHtml(leader?.program||leader?.savedLabel||leader?.name||"Not selected")}</li><li>CareerShield scores and six factors</li><li>10-year financial position</li><li>Estimated cost, debt, and time to earnings</li></ul></div><div><strong>What the family should decide next</strong><label>□ Which cost or pay assumption worries us most?</label><label>□ What result would change our current ranking?</label><label>□ Who will verify the school, employer, recruiter, or program claim?</label><label>□ What is our deadline for making this decision?</label></div></div><div class="family-write-in"><span>Our biggest unanswered question:</span><i></i><span>The next person or organization we will contact:</span><i></i></div><div class="family-next-step"><strong>Want to stress-test the comparison?</strong><p>Reopen CareerShield on this device, or log in to restore the saved paths. Deep Analysis ($9.99) tests lower pay, higher costs, delays, break-even timing, and missing assumptions. Human review remains optional.</p><b>${escapeHtml(location.origin)}</b></div></section>`}
const renderPlanBeforeFamilyWorksheet=renderPlan;
renderPlan=ranked=>{renderPlanBeforeFamilyWorksheet(ranked);const section=$("planSection");if(!ranked.length||!section)return;const qrHandoff=section.querySelector(".take-home-handoff");if(qrHandoff){const holder=document.createElement("div");holder.innerHTML=familyWorksheetMarkup(ranked);qrHandoff.replaceWith(holder.firstElementChild)}const printButton=section.querySelector(":scope > #printPlan");if(printButton){printButton.hidden=false;printButton.textContent="Print or save this family plan"}};
async function downloadFamilyWorksheet(ranked){const canvas=document.createElement("canvas");canvas.width=1275;canvas.height=1800;const ctx=canvas.getContext("2d"),start=Number(ranked[0]?.startAge||18),end=start+10,colors=["#155eef","#0a8f68","#d47a18","#7046b5"];ctx.fillStyle="#f3f7fc";ctx.fillRect(0,0,1275,1800);ctx.fillStyle="#071b30";ctx.fillRect(0,0,1275,245);const logo=await loadCanvasLogo();if(logo)ctx.drawImage(logo,65,30,320,128);else{ctx.fillStyle="#fff";ctx.font="800 42px Arial";ctx.fillText("CareerShield",65,90)}ctx.fillStyle="#83b5ff";ctx.font="800 20px Arial";ctx.fillText("FREE CAREER INVESTMENT COMPARISON",65,178);ctx.fillStyle="#fff";ctx.font="800 42px Arial";ctx.fillText(`Where could each path leave you by age ${end}?`,65,224);ranked.slice(0,4).forEach((option,index)=>{const y=285+index*205,confidence=option.dataConfidence||dataConfidence(option),weakest=Object.entries(option.metrics||{}).sort((a,b)=>a[1]-b[1])[0]?.[0]||"Assumptions";ctx.fillStyle="#fff";ctx.beginPath();ctx.roundRect(55,y,1165,175,18);ctx.fill();ctx.fillStyle=colors[index];ctx.fillRect(55,y,12,175);ctx.fillStyle="#071b30";ctx.font="800 26px Arial";canvasText(ctx,option.program||option.savedLabel||option.name,92,y+40,680);ctx.fillStyle="#536a80";ctx.font="400 17px Arial";canvasText(ctx,option.career?.name||option.pathLabel,92,y+70,680);ctx.fillStyle="#071b30";ctx.font="800 38px Arial";ctx.textAlign="right";ctx.fillText(`${option.score}/100`,1170,y+45);ctx.font="800 23px Arial";ctx.fillText(money(tenYearValue(option)),1170,y+78);ctx.textAlign="left";ctx.fillStyle="#315b8d";ctx.font="700 15px Arial";ctx.fillText(`Debt: ${money(option.inputs?.debt||0)}`,92,y+112);ctx.fillText(`Time to earnings: ${Math.round(Number(option.inputs?.duration||0))} months`,360,y+112);ctx.fillText(`Confidence: ${confidence.label} ${confidence.score}/100`,700,y+112);ctx.fillStyle="#9a5b12";ctx.fillText(`Watch closely: ${weakest}`,92,y+145)});const boxY=1140;ctx.fillStyle="#e8f2ff";ctx.beginPath();ctx.roundRect(55,boxY,1165,560,22);ctx.fill();ctx.fillStyle="#155eef";ctx.font="800 18px Arial";ctx.fillText("FAMILY DECISION WORKSHEET",90,boxY+47);ctx.fillStyle="#071b30";ctx.font="800 32px Arial";ctx.fillText("Turn the comparison into a family decision.",90,boxY+91);ctx.fillStyle="#536a80";ctx.font="400 17px Arial";ctx.fillText("Spend 15 minutes challenging the assumptions before anyone commits, enrolls, borrows, or signs.",90,boxY+126);ctx.fillStyle="#071b30";ctx.font="800 20px Arial";ctx.fillText("Discuss and check each item",90,boxY+180);ctx.font="400 18px Arial";["□ Which cost or pay assumption worries us most?","□ What result would change the current ranking?","□ Who will verify each school, employer, recruiter, or program claim?","□ What is our deadline for making this decision?"].forEach((line,i)=>ctx.fillText(line,90,boxY+220+i*39));ctx.font="800 18px Arial";ctx.fillText("Our biggest unanswered question:",90,boxY+405);ctx.strokeStyle="#8fa8c0";ctx.beginPath();ctx.moveTo(390,boxY+408);ctx.lineTo(1140,boxY+408);ctx.stroke();ctx.fillText("The next person or organization we will contact:",90,boxY+455);ctx.beginPath();ctx.moveTo(500,boxY+458);ctx.lineTo(1140,boxY+458);ctx.stroke();ctx.fillStyle="#155eef";ctx.font="800 18px Arial";ctx.fillText("NEXT STEP",90,boxY+510);ctx.fillStyle="#071b30";ctx.font="700 16px Arial";ctx.fillText("Reopen CareerShield on this device or log in to restore saved paths. Deep Analysis: $9.99.",210,boxY+510);ctx.fillStyle="#536a80";ctx.font="400 14px Arial";ctx.fillText(`${location.origin} · Directional decision support—not a guarantee. Verify all material claims.`,65,1760);await new Promise((resolve,reject)=>canvas.toBlob(blob=>{if(!blob)return reject(new Error("The family worksheet could not be created."));const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`careershield-family-decision-worksheet-age-${start}-to-${end}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);resolve()},"image/png"))}
downloadFreeComparisonSummary=downloadFamilyWorksheet;
render();

const familyWorksheetMarkupBeforeBeta=familyWorksheetMarkup;
familyWorksheetMarkup=ranked=>familyWorksheetMarkupBeforeBeta(ranked).replace("Deep Analysis ($9.99)","Deep Analysis beta (temporarily free)");
const downloadFamilyWorksheetBeforeBeta=downloadFamilyWorksheet;
downloadFamilyWorksheet=async ranked=>{const originalFillText=CanvasRenderingContext2D.prototype.fillText;CanvasRenderingContext2D.prototype.fillText=function(text,...args){const updated=typeof text==="string"?text.replace("Deep Analysis: $9.99.","Deep Analysis beta: temporarily free."):text;return originalFillText.call(this,updated,...args)};try{await downloadFamilyWorksheetBeforeBeta(ranked)}finally{CanvasRenderingContext2D.prototype.fillText=originalFillText}};
downloadFreeComparisonSummary=downloadFamilyWorksheet;
render();
